print('path',p)
for args in [[p,'--help'],[p,'-h'],[p]]:
    try:
        r=subprocess.run(args,input='',text=True,capture_output=True,timeout=20)
        print('ARGS',args,'RC',r.returncode)
        print((r.stdout+r.stderr)[:2000])
    except Exception as e: print(type(e).__name__,e)
print('file',subprocess.run(['file',p],text=True,capture_output=True).stdout)

